const reduceEntryMotion=()=>document.documentElement.dataset.motion==='off'||matchMedia('(prefers-reduced-motion: reduce)').matches;
function dismissIntro(immediate=false){
 const intro=$('#intro');skipIntro=true;booting=false;document.body.classList.remove('booting');
 if(!intro)return;
 intro.classList.add('intro-ready','intro-quiet');
 if(immediate){intro.remove();$('#main')?.focus({preventScroll:true});return}
 intro.classList.add('intro-leaving');setTimeout(()=>{intro.remove();$('#main')?.focus({preventScroll:true})},180);
}
async function finishIntro(){
 const intro=$('#intro');if(!intro){booting=false;document.body.classList.remove('booting');return}
 while(!skipIntro&&!reduceEntryMotion()&&performance.now()-entryStarted<4600)await new Promise(r=>setTimeout(r,50));
 if(skipIntro){dismissIntro(true);return}
 intro.classList.add('intro-ready');booting=false;document.body.classList.remove('booting');
 if(!reduceEntryMotion()){intro.classList.add('intro-leaving');await new Promise(r=>setTimeout(r,650));}
 intro.remove();if(document.activeElement===document.body)$('#main').focus({preventScroll:true});
}
$('#intro-skip')?.addEventListener('click',()=>dismissIntro(true));
setTimeout(()=>{if(booting)dismissIntro(true)},8000);
const app=$('#main');
function toast(message,error=false){const e=document.createElement('div');e.className='toast'+(error?' error':'');e.textContent=message;$('#toasts').append(e);setTimeout(()=>e.remove(),3500)}
function check(r){if(r.error)throw Error(r.error.message);return r.data}
function showError(e){toast(e.message||'暫時無法完成，請再試一次',true)}
function inventoryControls(root){for(const el of root.querySelectorAll('.item-link')){if(!el.querySelector('img')||el.dataset.itemHint)continue;const label=el.textContent.trim();el.dataset.itemHint=label;el.setAttribute('aria-label',label);for(const node of [...el.childNodes])if(node.nodeType===Node.TEXT_NODE){const span=document.createElement('span');span.className='inventory-label';span.textContent=node.textContent;node.replaceWith(span)}}}
function modal(title,body,itemId){$('#modal').classList.remove('boss-dialog');delete $('#modal').dataset.requestId;$('#modal-title').textContent=title;if(itemId&&icons[itemId])$('#modal-title').innerHTML=`<span class="item-title-icon" tabindex="0" data-item-hint="${h(title)}" aria-label="${h(title)}">${image(itemId)}</span>`;$('#modal-body').innerHTML=body;inventoryControls($('#modal-body'));if(!$('#modal').open)$('#modal').showModal()}
function keyState(){const remote=progress.get('settings:keys-'+KEY_VERSION)?.checklist;try{const local=JSON.parse(localStorage.getItem('iaa-keys-'+(user?.id||'guest')+'-'+KEY_VERSION)||'null');return ['complete','skipped'].includes(remote?.status)?remote:local||remote||{checks:{}}}catch{return remote||{checks:{}}}}
function rememberKeys(state){try{localStorage.setItem('iaa-keys-'+(user?.id||'guest')+'-'+KEY_VERSION,JSON.stringify(state))}catch{}}
function needsKeySetup(){return !['complete','skipped'].includes(keyState().status)}
function keysPage(){mountKeyGuide(app,{data:keyGuide,h,image,saved:keyState().checks,onSave:checks=>rememberKeys({status:'in-progress',checks}),onFinish:(status,checks)=>{const state={status,checks};rememberKeys(state);if(active)saveRecord('settings:keys-'+KEY_VERSION,{checklist:state,completed:status==='complete'}).catch(showError);go(keyReturn)}})}
function closeModal(){$('#modal').close()}
function route(){const hash=location.hash.slice(1)||'home',i=hash.indexOf('?');return {path:(i<0?hash:hash.slice(0,i)).split('/').map(decodeURIComponent),q:new URLSearchParams(i<0?'':hash.slice(i+1))}}
function go(path){location.hash=path}
const empty=text=>`<div class="empty">${h(text)}</div>`;
const notice=(text,warn=false)=>`<div class="notice${warn?' warn':''}">${h(text)}</div>`;
function percent(done,total){return total?Math.round(done/total*100):0}
function bar(done,total){return `<div class="progressbar"><span style="width:${percent(done,total)}%"></span></div><small>${done} / ${total} · ${percent(done,total)}%</small>`}
function image(id,cls=''){return icons[id]?`<img class="${cls}" src="${h(icons[id])}" alt="" loading="lazy" width="48" height="48">`:''}
function heading(title){return `<div class="page-heading"><h1>${h(title)}</h1></div>`}
function breadcrumb(title){return `<div class="breadcrumb"><a href="#home">世界</a> / ${h(title)}</div>`}
function atlasBreadcrumb(parts){
 const rows=Array.isArray(parts)?parts:[parts];
 return `<div class="breadcrumb"><a href="#collections">圖鑑</a>${rows.map((part,i)=>{const item=typeof part==='string'?{label:part}:part;return ' / '+(item.href&&i<rows.length?'<a href="'+h(item.href)+'">'+h(item.label)+'</a>':h(item.label))}).join('')}</div>`;
}
function finished(key){return !!progress.get(key)?.completed}
function wanted(key){return !!progress.get(key)?.checklist?.wish}
function wishlistToggle(key,label='加入想收集'){return `<label class="complete-check wishlist-check collection-state-button"><input type="checkbox" data-wish="${h(key)}" ${wanted(key)?'checked':''}><span class="wishlist-symbol" aria-hidden="true"></span><span>${h(label)}</span></label>`}
const JOURNEY_ORDER=['start','land','colony-start','factory','combat','expedition'];
