async function requestsTeam(){
 const rows=check(await db.from('requests').select('*').eq('team_id',teamId).order('created_at',{ascending:false}).limit(200)).filter(r=>r.status!=='cancelled'||r.author_id===user.id);
 requests=rows.sort((a,b)=>Number(a.status==='cancelled')-Number(b.status==='cancelled')||new Date(b.created_at)-new Date(a.created_at));$('#team-content').className='';$('#team-content').innerHTML=`<div class="actions"><button class="primary" data-request-new>＋ 發布需求／邀約</button><button data-team-refresh>重新整理</button></div><div class="request-board">${requests.map(r=>requestCard(r)).join('')}</div>${requests.length?'':empty('隊伍目前沒有申請。可以先發布一張材料需求或遠征邀約。')}`}
async function refreshTeamOrdersQuietly(){
 if(route().path[0]!=='team'||!teamId)return;
 const tab=route().q.get('tab')||'requests';
 if(tab==='requests')await requestsTeam();
 else if(tab==='notifications')await notificationsTeam();
 const dialog=$('#modal'),rid=dialog?.dataset.requestId;
 if(rid&&dialog?.open)await comments(rid);
}
const statusNames={open:'等待接單',claimed:'進行中',submitted:'待發布者確認',completed:'已完成',cancelled:'已取消'};
function playerName(id){return players.get(id)?.game_id||'隊員'}
function requestActions(r){let a='';if(r.status==='open'&&r.author_id!==user.id)a+=`<button data-request-action="claim" data-rid="${r.id}">接單</button>`;if(r.status==='claimed'&&r.assignee_id===user.id)a+=`<button data-request-action="submit" data-rid="${r.id}">提交完成</button><button data-request-action="release" data-rid="${r.id}">釋出接單</button>`;if(r.status==='submitted'&&r.author_id===user.id)a+=`<button class="primary" data-request-action="complete" data-rid="${r.id}">確認完成</button><button data-request-action="reopen" data-rid="${r.id}">退回</button>`;if(['open','claimed','submitted'].includes(r.status)&&r.author_id===user.id)a+=`<button data-request-action="cancel" data-rid="${r.id}">取消</button>`;if(r.status==='cancelled'&&r.author_id===user.id)a+=`<button class="primary" data-request-action="restore" data-rid="${r.id}">恢復</button>`;return a}
function rewardDisplay(r){return r.reward_item_id&&r.reward_quantity?`<span class="reward-stack" data-item-hint="${h(names[r.reward_item_id]||r.reward_item_id)}" aria-label="${h(names[r.reward_item_id]||r.reward_item_id)}">${image(r.reward_item_id)}<b>× ${r.reward_quantity}</b></span>`:h(r.reward||'')}
function requestCard(r){if(r.status==='cancelled'&&r.author_id!==user.id)return '';const itemName=r.kind==='item'?(names[r.item_id]||r.title):'';return `<article class="board-note ${r.reward?'bounty-note':''} ${r.status==='cancelled'?'cancelled-note':''}"><span class="note-pin" aria-hidden="true"></span><button class="board-note-open" data-comments="${r.id}" aria-label="查看${h(r.title)}"><span class="note-status">${r.reward?'懸賞 · ':''}${statusNames[r.status]}</span>${r.kind==='item'?`<span class="note-item" data-item-hint="${h(itemName)}" aria-label="${h(itemName)}">${image(r.item_id||'minecraft:chest')}<b>× ${r.quantity||1}</b></span><span class="note-title">${h(itemName)}</span>`:`<strong class="note-title">${h(r.title)}</strong>`}${r.reward?`<span class="note-reward">報酬 · ${rewardDisplay(r)}</span>`:''}<small>${h(playerName(r.author_id))}${r.assignee_id?' → '+h(playerName(r.assignee_id)):''}</small></button>${r.status==='open'&&r.author_id!==user.id?`<button class="request-claim" data-request-action="claim" data-rid="${r.id}">接單</button>`:''}</article>`}
function newRequest(id){
 const old=id?requests.find(r=>r.id===id):null;if(old&&(old.author_id!==user.id||old.status!=='open'))throw Error('只有發布者能編輯尚未被接單的需求');
 modal(old?'編輯需求／懸賞':'發布留言板',`<form id="request-form" class="form-grid"><label>類型<select name="kind"><option value="item" ${old?.kind==='item'?'selected':''}>物品申請</option><option value="mission" ${old?.kind==='mission'?'selected':''}>任務邀約</option></select></label><div id="request-item-fields"><div class="item-quantity-row"><label>申請物品<input id="request-item" list="request-items" autocomplete="off" placeholder="搜尋物品"></label><label>數量<input name="quantity" type="number" min="1" max="1000000" value="${old?.quantity||1}" required></label></div><datalist id="request-items"></datalist><div id="request-item-preview" class="item-preview"></div></div><label>標題（最多 32 字）<input name="title" maxlength="32" required value="${h(old?.title||'')}"></label><label>內容<textarea name="body" maxlength="4000">${h(old?.body||'')}</textarea></label><label class="inline"><input id="request-paid" type="checkbox" ${old?.reward_item_id?'checked':''}>提供懸賞報酬</label><div id="reward-field" ${old?.reward_item_id?'':'hidden'}><div class="item-quantity-row"><label>獎勵物品<input id="reward-item" list="reward-items" autocomplete="off" placeholder="搜尋物品" ${old?.reward_item_id?'':'disabled'}></label><label>數量<input id="reward-quantity" name="reward_quantity" type="number" min="1" max="1000000" value="${old?.reward_quantity||1}" ${old?.reward_item_id?'':'disabled'}></label></div><datalist id="reward-items"></datalist><div id="reward-item-preview" class="item-preview"></div></div><label>交付／集合地點<input name="location" maxlength="200" value="${h(old?.location||'')}"></label><label>預定時間（UTC+8）<input name="scheduled_at" type="datetime-local" value="${old?.scheduled_at?h(new Date(old.scheduled_at).toLocaleString('sv-SE',{timeZone:'Asia/Singapore'}).slice(0,16)):''}"></label><button class="primary">${old?'儲存修改':'張貼'}</button></form>`);
 const ids=Object.keys(requestItems).filter(id=>icons[id]),lookup=new Map(ids.map(id=>[`${names[id]} · ${id}`,id]));let chosen=old?.item_id||'',reward=old?.reward_item_id||'';
 function displayValue(id){return id&&names[id]?`${names[id]} · ${id}`:id||''}
 function picker(inputId,listId,previewId,onChoose,initial=''){const input=$('#'+inputId);input.value=displayValue(initial);const update=()=>{const q=input.value.trim(),id=lookup.get(q)||(ids.includes(q)?q:'');onChoose(id);const matches=ids.filter(id=>id.includes(q)||names[id].includes(q)).slice(0,40);$('#'+listId).innerHTML=matches.map(id=>`<option value="${h(names[id])} · ${h(id)}"></option>`).join('');$('#'+previewId).innerHTML=id?image(id)+`<span data-item-hint="${h(names[id])}" aria-label="${h(names[id])}">${h(names[id])}</span>`:''};input.oninput=update;update()}
 picker('request-item','request-items','request-item-preview',id=>{chosen=id;if(id&&!$('#request-form input[name=title]').value)$('#request-form input[name=title]').value=names[id].slice(0,32)},old?.item_id||'');picker('reward-item','reward-items','reward-item-preview',id=>reward=id,old?.reward_item_id||'');
 const syncKind=()=>{const item=$('#request-form select[name=kind]').value==='item';$('#request-item-fields').hidden=!item;$('#request-item').disabled=!item;$('#request-form input[name=quantity]').disabled=!item;$('#request-form input[name=quantity]').required=item};$('#request-form select[name=kind]').onchange=syncKind;syncKind();
 $('#request-paid').onchange=e=>{const paid=e.target.checked;$('#reward-field').hidden=!paid;for(const i of $('#reward-field').querySelectorAll('input')){i.disabled=!paid;i.required=paid}};
 $('#request-form').onsubmit=async e=>{e.preventDefault();const b=e.target.querySelector('button.primary');b.disabled=true;try{const d=Object.fromEntries(new FormData(e.target)),paid=$('#request-paid').checked;if(d.kind==='item'&&!chosen)throw Error('請從申請物品清單選擇一項');if(paid&&!reward)throw Error('請從獎勵物品清單選擇一項');const payload={kind:d.kind,title:d.title.trim(),body:d.body||'',item_id:d.kind==='item'?chosen:'',reward:paid?names[reward]+' × '+d.reward_quantity:'',reward_item_id:paid?reward:null,reward_quantity:paid?Number(d.reward_quantity):null,quantity:d.kind==='item'?Number(d.quantity):null,location:d.location||'',scheduled_at:d.scheduled_at?new Date(d.scheduled_at+':00+08:00').toISOString():null,updated_at:new Date().toISOString()};if(old)check(await db.from('requests').update(payload).eq('id',old.id));else check(await db.from('requests').insert({...payload,team_id:teamId,author_id:user.id}));closeModal();toast(old?'已更新需求／懸賞':'已張貼到隊伍留言板');await refreshTeamOrdersQuietly()}catch(e){showError(e)}finally{b.disabled=false}}
}
async function comments(id){let r=requests.find(x=>x.id===id);if(!r){try{r=check(await db.from('requests').select('*').eq('id',id).single());if(r)requests.push(r)}catch{return}}if(!r||r.status==='cancelled'&&r.author_id!==user.id)return;const rows=check(await db.from('request_comments').select('*').eq('request_id',id).order('created_at'));const assignee=r.assignee_id?`<p><b>接單者：</b>${h(playerName(r.assignee_id))}</p>`:`<p class="muted">目前尚未有人接單。</p>`;const own=r.author_id===user.id;const ownerTools=(own&&r.status==='open'?'<button data-request-edit="'+r.id+'">編輯</button>':'')+(own&&['open','cancelled'].includes(r.status)?'<button data-request-delete="'+r.id+'">刪除</button>':'');modal(r.title,`<p class="detail-body">${h(r.body)}</p>${r.kind==='item'?`<div class="note-item" data-item-hint="${h(names[r.item_id]||r.title)}" aria-label="${h(names[r.item_id]||r.title)}">${image(r.item_id||'minecraft:chest')}<b>× ${r.quantity||1}</b></div>`:''}${r.reward?`<p class="reward-detail">報酬 · ${rewardDisplay(r)}</p>`:''}<p>${h(r.location)}</p>${r.scheduled_at?`<p>${h(new Date(r.scheduled_at).toLocaleString('zh-TW',{timeZone:'Asia/Singapore'}))}（UTC+8）</p>`:''}<p><b>發布者：</b>${h(playerName(r.author_id))} · ${statusNames[r.status]}</p>${assignee}<div class="actions">${requestActions(r)}${ownerTools}</div><div class="mini-list">${rows.map(c=>`<section class="panel"><small>${h(playerName(c.author_id))} · ${h(new Date(c.created_at).toLocaleString('zh-TW'))}</small><p class="detail-body">${h(c.body)}</p></section>`).join('')||'<p class="muted">還沒有留言。</p>'}</div><form id="comment-form" class="form-grid"><label>回覆<textarea name="body" required maxlength="2000"></textarea></label><button class="primary">送出留言</button></form>`);$('#modal').dataset.requestId=id;$('#comment-form').onsubmit=async e=>{e.preventDefault();const b=e.target.querySelector('button');b.disabled=true;try{check(await db.from('request_comments').insert({request_id:id,author_id:user.id,body:new FormData(e.target).get('body')}));await comments(id)}catch(e){showError(e)}finally{b.disabled=false}}}
async function notificationsTeam(){
 let rows=[];
 try{rows=check(await db.from('request_notifications').select('*').eq('team_id',teamId).eq('user_id',user.id).order('created_at',{ascending:false}).limit(300))}catch(e){$('#team-content').className='';$('#team-content').innerHTML=notice('通知資料尚未啟用，請稍後重新整理。',true);return}
 $('#team-content').className='';
 $('#team-content').innerHTML=`<div class="notification-head"><h2>訂單通知</h2><button data-team-refresh>重新整理</button></div><div class="request-notifications">${rows.map(n=>`<article class="request-notification ${n.read_at?'':'unread'}"><div><strong>${h(n.title)}</strong><p>${h(n.message)}</p><small>${h(new Date(n.created_at).toLocaleString('zh-TW',{timeZone:'Asia/Singapore'}))}（UTC+8）</small></div>${n.request_id?`<button data-comments="${n.request_id}">查看訂單</button>`:''}</article>`).join('')||empty('目前沒有訂單通知。')}</div>`;
 const unread=rows.filter(n=>!n.read_at).map(n=>n.id);
 if(unread.length)try{check(await db.from('request_notifications').update({read_at:new Date().toISOString()}).in('id',unread));const bell=document.querySelector('.team-notification-bell');bell?.classList.remove('has-unread');bell?.querySelector('i')?.remove()}catch{}
}
async function compareTeam(){teamRows=[];for(let i=0;;i+=1000){const rows=check(await db.rpc('team_progress',{t:teamId}).order('user_id').order('record_key').range(i,i+999));teamRows.push(...rows);if(rows.length<1000)break}const shared=new Map();teamMembers.forEach(m=>{const p=players.get(m.user_id);shared.set(m.user_id,{id:m.user_id,profile:p,name:p?.game_id||'隊員',sharing:p?.share_progress===true,done:new Set()})});teamRows.forEach(r=>{const p=shared.get(r.user_id);if(p&&r.completed)p.done.add(r.record_key)});const all=[...collections.filter(x=>x.collectible),...advancements.map(x=>({key:'advancement:'+x.id,title:x.title,category:'advancements'}))];const cats=Object.entries(CATEGORIES),members=[...shared.values()],groups=[...cats.slice(0,4),['mounts','坐騎'],...cats.slice(4)];const rowsFor=k=>all.filter(x=>k==='mounts'?x.category==='companions'&&x.mount:x.category===k);
 $('#team-content').className='';$('#team-content').innerHTML=`<h2>收藏競賽</h2><div class="collection-races">${groups.map(([k,v],index)=>{const rows=rowsFor(k),entrants=members.map(p=>({...p,count:rows.filter(x=>p.done.has(x.key)).length})).sort((a,b)=>Number(b.sharing)-Number(a.sharing)||b.count-a.count||a.name.localeCompare(b.name));return `<details class="race-category" ${index===0?'open':''}><summary>${h(v)}</summary><div class="race-lanes">${entrants.map((p,i)=>`<div class="race-lane ${!p.sharing?'race-private':''}"><span class="race-rank">${p.sharing?i+1:'—'}</span><div class="race-course"><div class="race-road"><i style="width:${p.sharing?percent(p.count,rows.length):0}%"></i></div><button class="race-runner" style="left:${p.sharing?percent(p.count,rows.length):0}%" data-item-hint="${h(p.name)}${p.sharing?' · '+p.count+' / '+rows.length:' · 未分享'}" aria-label="${h(p.name)}：${p.sharing?percent(p.count,rows.length)+'%':'未分享'}">${avatarImage(p.profile,cfg,h)}</button></div><span class="race-score">${p.sharing?percent(p.count,rows.length)+'%':'未分享'}</span></div>`).join('')}</div></details>`}).join('')}</div><section class="panel"><h3>逐項比較</h3><form id="compare-filter" class="collection-search"><input name="q" aria-label="搜尋比較項目" placeholder="搜尋收藏名稱…"><details class="filter-drawer"><summary>篩選</summary><div class="filter-options"><select name="category" aria-label="比較收藏類型">${groups.map(([k,v])=>`<option value="${k}">${v}</option>`).join('')}</select><button>套用</button></div></details></form><div id="compare-table"></div></section>`;
 let comparePage=1;function draw(cat,needle=''){const rows=rowsFor(cat).filter(x=>x.title.toLowerCase().includes(needle.toLowerCase()));$('#compare-table').innerHTML=`<p class="muted">${rows.length} 筆 · 第 ${comparePage} / ${Math.max(1,Math.ceil(rows.length/60))} 頁</p><div class="comparison-scroll"><table class="item-matrix"><thead><tr><th>收藏項目</th>${members.map(p=>`<th title="${h(p.name)}">${h(p.name)}</th>`).join('')}</tr></thead><tbody>${rows.slice((comparePage-1)*60,comparePage*60).map(x=>`<tr><th><a href="#${x.category==='advancements'?'advance/'+enc(x.key.slice(12)):'record/'+enc(x.key)}">${h(x.title)}</a></th>${members.map(p=>`<td class="${p.sharing&&p.done.has(x.key)?'checkmark':''}" data-player="${h(p.name)}" aria-label="${h(p.name)}：${!p.sharing?'未分享':p.done.has(x.key)?'已完成':'未完成'}">${!p.sharing?'·':p.done.has(x.key)?'✓':'—'}</td>`).join('')}</tr>`).join('')}</tbody></table></div><div class="pager"><button id="compare-prev" ${comparePage===1?'disabled':''}>← 上頁</button><button id="compare-next" ${comparePage*60>=rows.length?'disabled':''}>下頁 →</button></div>`;$('#compare-prev').onclick=()=>{comparePage--;draw(cat,needle)};$('#compare-next').onclick=()=>{comparePage++;draw(cat,needle)}}draw('equipment');$('#compare-filter').onsubmit=e=>{e.preventDefault();const d=new FormData(e.target);comparePage=1;draw(d.get('category'),d.get('q'))};}
async function recordsTeam(){teamRecords=check(await db.from('team_records').select('*').eq('team_id',teamId).order('updated_at',{ascending:false}).limit(200));$('#team-content').className='';$('#team-content').innerHTML=`<button class="primary" data-record-new>＋ 新增據點／計畫／里程碑</button><div class="grid" style="margin-top:18px">${teamRecords.map(r=>`<section class="card"><span class="tag">${{base:'共享據點',plan:'建設計畫',milestone:'世界里程碑'}[r.kind]}</span><h3>${h(r.title)}</h3><p class="detail-body">${h(r.body)}</p><small>${h(playerName(r.author_id))}</small>${r.author_id===user.id||canManageTeam()?`<button data-record-edit="${r.id}">編輯</button>`:''}</section>`).join('')}</div>`}
