window.addEventListener('online',()=>{toast('已恢復網路連線');if(teamId)subscribeTeam().catch(showError)});
async function init(){try{cfg=await fetch('site-config.json').then(r=>r.json());document.title=cfg.siteTitle;[articles,collections,advancements,icons,summary,recipes,originals,names,materialTags,keyGuide,requestItems]=await Promise.all(['articles','collections','advancements','icons','summary','tutorial-recipes','originals','names','tutorial-item-tags','key-guide','request-items'].map(name=>fetch('data/'+name+'.json').then(r=>{if(!r.ok)throw Error('攻略資料載入失敗');return r.json()})));for(const [id,label]of Object.entries(requestItems))if(!names[id])names[id]=label;collections=collections.filter(x=>x.category!=='skills'||x.collectible);db=createClient(cfg.supabaseUrl,cfg.supabaseKey,{auth:{persistSession:true,autoRefreshToken:true}});$('#desktop-nav').innerHTML=NAV.map(([id,icon,name])=>`<a data-nav="${id}" href="#${id}"><span class="nav-icon">${navIcon(id)}</span>${name}</a>`).join('');$('#mobile-nav').innerHTML=NAV.map(([id,icon,name])=>`<a data-nav="${id}" href="#${id}"><span class="nav-icon">${navIcon(id)}</span>${name}</a>`).join('');$('#intro-name').innerHTML=`<span class="intro-name-zh">${h(cfg.serverNameZh)}</span><span class="intro-name-en">${h(cfg.serverNameEn)}</span>`;$('#intro-status').textContent='正在確認冒險者身分…';try{await loadAccount()}catch(e){cloudUnavailable=true;active=false;toast('雲端紀錄暫時無法連線，攻略仍可閱讀。請稍後重試。',true)}history.replaceState(null,'','#'+(user?'me':initialHash.startsWith('#auth?')?initialHash.slice(1):'auth'));
 await render();await finishIntro();db.auth.onAuthStateChange((event,session)=>{if(event==='TOKEN_REFRESHED')user=session?.user||null;if(event==='SIGNED_OUT'&&user){user=null;active=false;progress.clear();if(channel){db.removeChannel(channel);channel=null}updateAccountLabel();render().catch(showError)}})}catch(e){app.innerHTML=notice('載入失敗，請確認網路後重新整理。'+e.message,true)+`<button id="reload-entry">重新開啟手札</button>`;$('#reload-entry').onclick=()=>location.reload();skipIntro=true;await finishIntro();}}
init();

let popupContext=null;
function advancementModal(id){
 const x=advancements.find(x=>x.id===id);if(!x)return;
 const key='advancement:'+id;
 const groups=x.requirements.map((g,i)=>`<section class="condition-group"><b>第 ${i+1} 組${g.length>1?' · 選一項':''}</b>${g.map(k=>{const q=x.criteria.find(c=>c.key===k);return `<div class="modal-condition">• ${h(q?.instruction||k)}</div>`}).join('')}</section>`).join('');
 modal(x.title,`<div class="atlas-modal-detail"><div class="modal-atlas-state">${atlasStateButtons(key)}</div><span class="tag">${h(groupFor(id.split(':')[0]))}${x.hidden?' · 隱藏成就':''}</span><p class="article-intro">${h(x.description)}</p><h3>如何完成</h3>${groups}${x.customTrigger?notice('這項成就包含模組自訂或程式觸發條件。'):''}</div>`);
}
function collectionModal(key){
 const x=collections.find(x=>x.key===key);if(!x)return;
 const modalCategory=x.mount?'mounts':x.category;
 const atlas=ATLASES.find(a=>a[0]===modalCategory)||ATLASES.find(a=>a[4]===x.sourceGuide);if(!atlas)return;
 const [category,,title,,slug]=atlas,g=originals.find(g=>g.id===slug);if(!g)return;
 const uid=user?.id||'guest',saved=progress.get('guide:'+slug)?.checklist||{},data=active?writeGuide(slug,saved,progress,collections):saved;
 for(const [k,v]of Object.entries(data))localStorage.setItem('iaa-guide-'+uid+'-'+slug+'-'+k,v);
 popupContext={slug,category,item:x.category==='strategy'?x.key.replace('scarlet:',''):x.id,query:x.title,reference:!x.collectible,mode:'all'};
 modal(x.title,`<iframe id="atlas-modal-frame" class="boss-modal-frame" title="${h(x.title)}" src="${g.path}?player=${enc(uid)}&atlas=${enc(slug)}&section=${enc(category)}&popup=1&reader=20261006-aoi19"></iframe>`);
 $('#modal').classList.add('boss-dialog');
 const modalFrame=$('#atlas-modal-frame');modalFrame?.addEventListener('load',()=>refreshAtlasReader(modalFrame),{once:true});
}
async function bossModal(id){
 const x=collections.find(x=>x.category==='bosses'&&x.id===id);if(x)collectionModal(x.key);
}
document.addEventListener('boss-reference',e=>bossModal(e.detail).catch(showError));
$('#modal').addEventListener('close',()=>{$('#modal').classList.remove('boss-dialog');$('#atlas-modal-frame')?.remove();popupContext=null});
const feedbackStatuses={not_started:'未開始',reviewed:'已審閱',in_progress:'進行中',completed:'已完成'};
let feedbackRows=[];
async function feedbackPage(){if(!needAccount())return;const all=isAdmin&&route().q.get('all')==='1';let query=db.from('feedback').select('*').order('created_at',{ascending:false});if(!all)query=query.eq('author_id',user.id);feedbackRows=[];for(let offset=0;;offset+=1000){const rows=check(await query.range(offset,offset+999));feedbackRows.push(...rows);if(rows.length<1000)break}
 app.innerHTML=heading(all?'網站反饋管理':'我的反饋')+`<div class="actions"><button class="primary" data-feedback-new>＋ 提交反饋</button>${isAdmin?`<a class="btn" href="#feedback${all?'':'?all=1'}">${all?'只看我的反饋':'查看全部反饋'}</a>`:''}<a class="btn" href="#me">返回我的頁面</a></div><form id="feedback-filter" class="collection-search"><input name="q" placeholder="搜尋反饋…" aria-label="搜尋反饋"><details class="filter-drawer"><summary>篩選</summary><div class="filter-options"><select name="status" aria-label="反饋狀態"><option value="">全部狀態</option>${Object.entries(feedbackStatuses).map(([k,v])=>`<option value="${k}">${v}</option>`).join('')}</select><button>套用</button></div></details></form><div id="feedback-list"></div>`;
 const draw=()=>{const f=new FormData($('#feedback-filter')),rows=feedbackRows.filter(r=>(!f.get('status')||r.status===f.get('status'))&&(r.title+' '+r.body).toLowerCase().includes(String(f.get('q')||'').toLowerCase()));$('#feedback-list').innerHTML=rows.map(r=>`<button class="feedback-card" data-feedback-open="${r.id}"><span class="feedback-status feedback-${r.status}">${feedbackStatuses[r.status]}</span><h3>${h(r.title)}</h3><small>${r.kind==='idea'?'功能建議':'問題回報'} · ${h(new Date(r.created_at).toLocaleDateString('zh-TW'))}</small>${r.admin_reply?'<span class="reply-indicator">管理員已回覆</span>':''}</button>`).join('')||empty('目前沒有反饋。')};draw();$('#feedback-filter').onsubmit=e=>{e.preventDefault();draw();$('#feedback-filter details').open=false};
}
function newFeedback(){modal('提交網站反饋',`<form id="feedback-form" class="form-grid"><label>類型<select name="kind"><option value="issue">問題回報</option><option value="idea">功能建議</option></select></label><label>標題<input name="title" required maxlength="60"></label><label>內容<textarea name="body" required maxlength="4000" placeholder="遇到問題時，請描述在哪個頁面、如何操作，以及預期結果。"></textarea></label><button class="primary">提交</button></form>`);$('#feedback-form').onsubmit=async e=>{e.preventDefault();const b=e.target.querySelector('button');b.disabled=true;try{const d=Object.fromEntries(new FormData(e.target));check(await db.from('feedback').insert({...d,title:d.title.trim(),body:d.body.trim(),author_id:user.id}));closeModal();toast('反饋已送交網站管理員');await feedbackPage()}catch(e){showError(e)}finally{b.disabled=false}}}
async function openFeedback(id){const r=check(await db.from('feedback').select('*').eq('id',id).single());modal(r.title,`<span class="feedback-status feedback-${r.status}">${feedbackStatuses[r.status]}</span><p class="detail-body">${h(r.body)}</p>${r.admin_reply?`<section class="panel"><h3>管理員回覆</h3><p class="detail-body">${h(r.admin_reply)}</p></section>`:''}${isAdmin?`<form id="feedback-review" class="form-grid"><label>處理狀態<select name="status">${Object.entries(feedbackStatuses).map(([k,v])=>`<option value="${k}" ${r.status===k?'selected':''}>${v}</option>`).join('')}</select></label><label>回覆／處理結果<textarea name="reply" maxlength="4000">${h(r.admin_reply)}</textarea></label><button class="primary">保存處理狀態</button></form>`:''}`);if(isAdmin)$('#feedback-review').onsubmit=async e=>{e.preventDefault();const b=e.target.querySelector('button');b.disabled=true;try{const d=new FormData(e.target);check(await db.rpc('review_feedback',{f:id,s:d.get('status'),reply:d.get('reply')}));closeModal();toast('反饋狀態已更新');await feedbackPage()}catch(e){showError(e)}finally{b.disabled=false}}}

function editAvatar(){if(!needAccount())return;openAvatarEditor({profile,user,db,cfg,h,modal,check,onSaved:p=>{profile=p;updateAccountLabel();closeModal();toast("頭像已更新");render().catch(showError)},onError:showError})}
setInterval(async()=>{if(!active||document.visibilityState!=='visible')return;const rows=[profile,...players.values()].filter(Boolean);await resolveAvatars(rows,db);const byId=new Map(rows.map(p=>[p.id,p]));for(const image of document.querySelectorAll('img.player-avatar[data-avatar-user]')){const p=byId.get(image.dataset.avatarUser);if(p?.avatar_path&&p.avatar_url)image.src=p.avatar_url;}},240000);